<script lang="ts">
  import { appStore } from '../state/store.svelte';
  import { pendingConfirm, resolveConfirm } from '../confirm';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';

  const request = $derived(pendingConfirm());

  function close() {
    resolveConfirm(false);
  }
</script>

{#if appStore.confirmDialog && request}
  <AppDialog
    title={request.title}
    description={request.description}
    iconName={request.danger ? 'Warning' : request.info ? 'Info' : 'QuestionCircle'}
    size="small"
    flush={!request.detail}
    onClose={close}
  >
    <!-- 长串 (完整路径、错误原文) 放正文: 标题下那行是 12px 副标题, 塞路径会被挤成一团,
         而且它不保留换行 —— 提示类消息常用 `\n\n` 分段。`.confirm-message` 是 `pre-wrap`。 -->
    {#if request.detail}
      <p class="confirm-message" title={request.detail}>{request.detail}</p>
    {/if}

    {#snippet footer()}
      {#if request.info}
        <Button appearance="primary" onclick={() => resolveConfirm(true)}>
          {request.confirmLabel ?? '知道了'}
        </Button>
      {:else}
        <Button appearance="subtle" onclick={close}>{request.cancelLabel ?? '取消'}</Button>
        <Button appearance={request.danger ? 'danger' : 'primary'} onclick={() => resolveConfirm(true)}>
          {request.confirmLabel ?? '确定'}
        </Button>
      {/if}
    {/snippet}
  </AppDialog>
